def compress(s: str) -> str:
    """Return the run-length encoding of s, for example "aaabcc" -> "a3b1c2"."""
    result = []
    current_char = ""
    count = 0

    for char in s:
        if char == current_char:
            count += 1
        else:
            if count > 1:
                result.append(f"{current_char}{count}")
            current_char = char
            count = 1

    # Add the last group if it's not empty
    if count > 1:
        result.append(f"{current_char}{count}")

    return ''.join(result)

# Example usage:
